VALUES (
    'E31C',
    'E31C Visa Keluarga Anak Hasil Perkawinan Sah WNA-WNI',
    'KITAS/Limited Stay',
    'E31',
    'E31C Visa Keluarga Anak Hasil Perkawinan Sah WNA-WNI',
    'ITAS',
    NULL,
