    'MULTIPLE',
    'REQUIRED',
    NULL,
    NULL,
    TRUE,
    NULL,
    NULL,
    NULL,
    $j${"allowed_activities": "melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "code": "E31C", "definition_verbatim": "melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "entry": "multiple", "extendable": ["Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"], "http_status": 200, "itap_assessment": {"direct_itap_context_present": true, "family_evidence": "law/E31/ITAP.json", "itas_to_itap_eligible_as_stated": null, "status": "TO_VERIFY"}, "itap_verbatim": [{"kind": "generic_conversion", "section": "Jenis visa", "text": "Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E31C"}, {"kind": "direct_itap_context", "section": "GCI news", "text": "Permohonan GCI diajukan secara daring melalui sistem visa elektronik (evisa.imigrasi.go.id). E-visa GCI (indeks E31A, E31B, E31C, E32E, E32F, E32G, E32H) terintegrasi dengan sistem perlintasan, baik autogate maupun konter pemeriksaan imigrasi manual. Pemohon yang ingin menggunakan fasilitas autogate diwajibkan mengisi deklarasi kedatangan All Indonesia sebelum tiba di RI. Dalam kurun waktu 24 jam setelah memasuki Indonesia, pemegang e-visa GCI akan langsung menerima Izin Tinggal Tetap (ITAP) tak terbatas, tanpa perlu pergi ke kantor imigrasi.", "url": "https://jakartapusat.imigrasi.go.id/berita/imigrasi-resmikan-global-citizen-of-indonesia-di-hari-bakti-imigrasi-ke-76"}], "jenis_visa_verbatim": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "ketentuan_lain_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."], "not_found_evidence_verbatim": null, "notes": ["VERIFIED_FROM_SOURCE denotes faithful capture of the available page, not resolution of legal conflicts or missing fields.", "Only HTML entities, whitespace and structural list markers are normalized. Source spelling, punctuation, amounts and nested alternatives are retained.", "No offshore/onshore statement was found on the visa page; where_to_apply is null + TO_VERIFY. The evisa application channel is preserved separately.", "stay_days retains source year-based sentences; no conversion to a day count. total_max_verbatim is null when the visa page gives no cumulative limit.", "PNBP is reference only and is never a client price.", "Requirement numbers are extraction order, not official numbering. Nested alternatives remain grouped; section context and translation exceptions must be read with the items.", "A generic conversion sentence or a relative holding ITAP does not establish that this code can convert to ITAP. Code-specific conversion eligibility remains null + TO_VERIFY; see ITAP.json."], "official_name_id": "E31C Visa Keluarga Anak Hasil Perkawinan Sah WNA-WNI", "page_sha256": "5eaa7e1596a9c1752ddf5d0c3b252e70917cf0bebae27e491b36b174f3193d4d", "pengajuan_intro_verbatim": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:", "persyaratan_khusus_verbatim": "- Bukti kelahiran berupa Akta kelahiran yang dikeluarkan oleh kementerian atau lembaga berwenang; atau Bukti pelaporan kelahiran pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil (jika Orang Asing lahir di luar wilayah Indonesia).\n- Bukti perkawinan orang tua berupa: Bukti pelaporan atau pencatatan pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil dan akta perkawinan yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*; atau Buku nikah atau akta perkawinan yang dikeluarkan oleh kementerian atau lembaga berwenang (jika perkawinan dilakukan di wilayah Indonesia).\n- Kartu Keluarga (KK) ayah/ibu Warga Negara Indonesia.", "pnbp_verbatim_for_reference_only": ["Masa tinggal 1 tahun : Rp. 6.000.000,-", "Komponen Biaya:", "- Biaya visa Rp 500.000", "- Izin tinggal terbatas Rp 3.000.000", "- Izin masuk kembali Rp 1.500.000", "- Biaya Verifikasi I Rp 1.000.000", "Masa tinggal 2 tahun : Rp. 8.500.000,-", "Komponen Biaya:", "- Biaya visa Rp 500.000", "- Izin tinggal terbatas Rp 5.000.000", "- Izin masuk kembali Rp 2.000.000", "- Biaya Verifikasi I Rp 1.000.000"], "prohibited_or_conditions_verbatim": ["melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."], "raw_path": "raw/E31C.html", "requirements_context_verbatim": [{"section": "Pengajuan visa", "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:"}], "requirements_reference_verbatim": null, "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "Surat permohonan visa dari ayah/ibu Warga Negara Indonesia"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis, (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "Daftar riwayat hidup"}, {"n": 6, "section": "Pengajuan visa (berkas elektronik)", "text": "Riwayat perjalanan (itinerary)"}, {"n": 7, "section": "Persyaratan khusus", "text": "Bukti kelahiran berupa Akta kelahiran yang dikeluarkan oleh kementerian atau lembaga berwenang; atau Bukti pelaporan kelahiran pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil (jika Orang Asing lahir di luar wilayah Indonesia)."}, {"n": 8, "section": "Persyaratan khusus", "text": "Bukti perkawinan orang tua berupa: Bukti pelaporan atau pencatatan pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil dan akta perkawinan yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*; atau Buku nikah atau akta perkawinan yang dikeluarkan oleh kementerian atau lembaga berwenang (jika perkawinan dilakukan di wilayah Indonesia)."}, {"n": 9, "section": "Persyaratan khusus", "text": "Kartu Keluarga (KK) ayah/ibu Warga Negara Indonesia."}], "retrieved_at": "2026-10-17T13:27:12Z", "sections_verbatim": [{"blocks": [{"kind": "context", "text": "melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"}], "heading": "Dengan visa ini, anda dapat", "id": "dengan-visa-ini-anda-dapat", "items": ["melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.", "Selama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"], "text": "melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"}, {"blocks": [{"kind": "context", "text": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya."}], "heading": "Jenis visa", "id": "jenis-visa", "items": ["Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.", "Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya."], "text": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya."}, {"blocks": [{"kind": "item", "text": "Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan."}, {"kind": "item", "text": "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"}], "heading": "Masa tinggal", "id": "masa-tinggal", "items": ["Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan.", "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"], "text": "- Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan.\n- Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"}, {"blocks": [{"kind": "context", "text": "Masa tinggal 1 tahun : Rp. 6.000.000,-\nKomponen Biaya:"}, {"kind": "item", "text": "Biaya visa Rp 500.000"}, {"kind": "item", "text": "Izin tinggal terbatas Rp 3.000.000"}, {"kind": "item", "text": "Izin masuk kembali Rp 1.500.000"}, {"kind": "item", "text": "Biaya Verifikasi I Rp 1.000.000"}, {"kind": "context", "text": "Masa tinggal 2 tahun : Rp. 8.500.000,-\nKomponen Biaya:"}, {"kind": "item", "text": "Biaya visa Rp 500.000"}, {"kind": "item", "text": "Izin tinggal terbatas Rp 5.000.000"}, {"kind": "item", "text": "Izin masuk kembali Rp 2.000.000"}, {"kind": "item", "text": "Biaya Verifikasi I Rp 1.000.000"}], "heading": "Biaya (PNBP)", "id": "biaya-pnbp", "items": ["Biaya visa Rp 500.000", "Izin tinggal terbatas Rp 3.000.000", "Izin masuk kembali Rp 1.500.000", "Biaya Verifikasi I Rp 1.000.000", "Biaya visa Rp 500.000", "Izin tinggal terbatas Rp 5.000.000", "Izin masuk kembali Rp 2.000.000", "Biaya Verifikasi I Rp 1.000.000"], "text": "Masa tinggal 1 tahun : Rp. 6.000.000,-\nKomponen Biaya:\n- Biaya visa Rp 500.000\n- Izin tinggal terbatas Rp 3.000.000\n- Izin masuk kembali Rp 1.500.000\n- Biaya Verifikasi I Rp 1.000.000\nMasa tinggal 2 tahun : Rp. 8.500.000,-\nKomponen Biaya:\n- Biaya visa Rp 500.000\n- Izin tinggal terbatas Rp 5.000.000\n- Izin masuk kembali Rp 2.000.000\n- Biaya Verifikasi I Rp 1.000.000"}, {"blocks": [{"kind": "context", "text": "Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."}], "heading": "Penjamin (Sponsor)", "id": "penjamin-sponsor", "items": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."], "text": "Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."}, {"blocks": [{"kind": "context", "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:"}, {"kind": "item", "text": "Surat permohonan visa dari ayah/ibu Warga Negara Indonesia"}, {"kind": "item", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis, (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)"}, {"kind": "item", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara"}, {"kind": "item", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"kind": "item", "text": "Daftar riwayat hidup"}, {"kind": "item", "text": "Riwayat perjalanan (itinerary)"}], "heading": "Pengajuan visa", "id": "pengajuan-visa", "items": ["Surat permohonan visa dari ayah/ibu Warga Negara Indonesia", "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis, (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)", "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara", "pasfoto berwarna terbaru (setahun terakhir). Detail", "Daftar riwayat hidup", "Riwayat perjalanan (itinerary)"], "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:\n- Surat permohonan visa dari ayah/ibu Warga Negara Indonesia\n- Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis, (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)\n- bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara\n- pasfoto berwarna terbaru (setahun terakhir). Detail\n- Daftar riwayat hidup\n- Riwayat perjalanan (itinerary)"}, {"blocks": [{"kind": "item", "text": "Bukti kelahiran berupa Akta kelahiran yang dikeluarkan oleh kementerian atau lembaga berwenang; atau Bukti pelaporan kelahiran pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil (jika Orang Asing lahir di luar wilayah Indonesia)."}, {"kind": "item", "text": "Bukti perkawinan orang tua berupa: Bukti pelaporan atau pencatatan pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil dan akta perkawinan yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*; atau Buku nikah atau akta perkawinan yang dikeluarkan oleh kementerian atau lembaga berwenang (jika perkawinan dilakukan di wilayah Indonesia)."}, {"kind": "item", "text": "Kartu Keluarga (KK) ayah/ibu Warga Negara Indonesia."}], "heading": "Persyaratan khusus", "id": "persyaratan-khusus", "items": ["Bukti kelahiran berupa Akta kelahiran yang dikeluarkan oleh kementerian atau lembaga berwenang; atau Bukti pelaporan kelahiran pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil (jika Orang Asing lahir di luar wilayah Indonesia).", "Bukti perkawinan orang tua berupa: Bukti pelaporan atau pencatatan pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil dan akta perkawinan yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*; atau Buku nikah atau akta perkawinan yang dikeluarkan oleh kementerian atau lembaga berwenang (jika perkawinan dilakukan di wilayah Indonesia).", "Kartu Keluarga (KK) ayah/ibu Warga Negara Indonesia."], "text": "- Bukti kelahiran berupa Akta kelahiran yang dikeluarkan oleh kementerian atau lembaga berwenang; atau Bukti pelaporan kelahiran pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil (jika Orang Asing lahir di luar wilayah Indonesia).\n- Bukti perkawinan orang tua berupa: Bukti pelaporan atau pencatatan pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil dan akta perkawinan yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*; atau Buku nikah atau akta perkawinan yang dikeluarkan oleh kementerian atau lembaga berwenang (jika perkawinan dilakukan di wilayah Indonesia).\n- Kartu Keluarga (KK) ayah/ibu Warga Negara Indonesia."}, {"blocks": [{"kind": "item", "text": "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia."}, {"kind": "item", "text": "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal."}, {"kind": "item", "text": "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi."}, {"kind": "item", "text": "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."}], "heading": "Ketentuan lain", "id": "ketentuan-lain", "items": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."], "text": "- Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.\n- Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.\n- Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.\n- Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."}, {"blocks": [{"kind": "context", "text": "Pengajuan Visa di Direktorat Jenderal Imigrasi:"}, {"kind": "item", "text": "pemeriksaan kelengkapan persyaratan;"}, {"kind": "item", "text": "verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;"}, {"kind": "item", "text": "pembuatan profil dan verifikasi;"}, {"kind": "item", "text": "persetujuan;"}, {"kind": "item", "text": "penerbitan visa."}, {"kind": "context", "text": "Waktu proses lima hari kerja setelah pembayaran visa diterima."}], "heading": "Proses pengajuan dan pemberian visa", "id": "proses-pengajuan-dan-pemberian-visa", "items": ["pemeriksaan kelengkapan persyaratan;", "verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;", "pembuatan profil dan verifikasi;", "persetujuan;", "penerbitan visa."], "text": "Pengajuan Visa di Direktorat Jenderal Imigrasi:\n- pemeriksaan kelengkapan persyaratan;\n- verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;\n- pembuatan profil dan verifikasi;\n- persetujuan;\n- penerbitan visa.\nWaktu proses lima hari kerja setelah pembayaran visa diterima."}, {"blocks": [{"kind": "item", "text": "Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM"}, {"kind": "item", "text": "Peraturan Menteri Hukum dan HAM RI Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal"}, {"kind": "item", "text": "Peraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal"}, {"kind": "item", "text": "Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa"}, {"kind": "item", "text": "Peraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI"}, {"kind": "item", "text": "Peraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"}], "heading": "Dasar hukum", "id": "dasar-hukum", "items": ["Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM", "Peraturan Menteri Hukum dan HAM RI Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal", "Peraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal", "Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa", "Peraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI", "Peraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"], "text": "- Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM\n- Peraturan Menteri Hukum dan HAM RI Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal\n- Peraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal\n- Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa\n- Peraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI\n- Peraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"}], "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E31C", "sponsor_required": {"as_stated_boolean": true, "invitation_requirement_see": "requirements_verbatim", "verbatim": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan."], "subjek_verbatim": null, "to_verify": ["where_to_apply", "itas_to_itap_eligible_as_stated", "total_max_verbatim"], "total_max_verbatim": null, "verification_issues": [{"finding": "The official GCI news names this index and direct ITAP, whereas the visa page describes ITAS. Route applicability is unresolved; direct issuance is not ITAS-to-ITAP conversion.", "id": "GCI_DIRECT_ITAP_VS_VISA_PAGE_ITAS", "quotes": [{"section": "Jenis visa", "text": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E31C"}, {"section": "GCI news", "text": "Permohonan GCI diajukan secara daring melalui sistem visa elektronik (evisa.imigrasi.go.id). E-visa GCI (indeks E31A, E31B, E31C, E32E, E32F, E32G, E32H) terintegrasi dengan sistem perlintasan, baik autogate maupun konter pemeriksaan imigrasi manual. Pemohon yang ingin menggunakan fasilitas autogate diwajibkan mengisi deklarasi kedatangan All Indonesia sebelum tiba di RI. Dalam kurun waktu 24 jam setelah memasuki Indonesia, pemegang e-visa GCI akan langsung menerima Izin Tinggal Tetap (ITAP) tak terbatas, tanpa perlu pergi ke kantor imigrasi.", "url": "https://jakartapusat.imigrasi.go.id/berita/imigrasi-resmikan-global-citizen-of-indonesia-di-hari-bakti-imigrasi-ke-76"}], "status": "TO_VERIFY"}], "where_to_apply": null}$j$::jsonb,
