    NULL,
    $j${"allowed_activities": "melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "code": "E31D", "definition_verbatim": "melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "entry": "multiple", "extendable": ["Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"], "http_status": 200, "itap_assessment": {"direct_itap_context_present": false, "family_evidence": "law/E31/ITAP.json", "itas_to_itap_eligible_as_stated": null, "status": "TO_VERIFY"}, "itap_verbatim": [{"kind": "generic_conversion", "section": "Jenis visa", "text": "Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E31D"}], "jenis_visa_verbatim": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "ketentuan_lain_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."], "not_found_evidence_verbatim": null, "notes": ["VERIFIED_FROM_SOURCE denotes faithful capture of the available page, not resolution of legal conflicts or missing fields.", "Only HTML entities, whitespace and structural list markers are normalized. Source spelling, punctuation, amounts and nested alternatives are retained.", "No offshore/onshore statement was found on the visa page; where_to_apply is null + TO_VERIFY. The evisa application channel is preserved separately.", "stay_days retains source year-based sentences; no conversion to a day count. total_max_verbatim is null when the visa page gives no cumulative limit.", "PNBP is reference only and is never a client price.", "Requirement numbers are extraction order, not official numbering. Nested alternatives remain grouped; section context and translation exceptions must be read with the items.", "A generic conversion sentence or a relative holding ITAP does not establish that this code can convert to ITAP. Code-specific conversion eligibility remains null + TO_VERIFY; see ITAP.json."], "official_name_id": "E31D Visa Keluarga Anak Bawaan WNA Perkawinan Sah WNA-WNI", "page_sha256": "2f5c807032c41adaa942a56bfac65f1099e5b5c6ffec9f0605fb76e185f999b0", "pengajuan_intro_verbatim": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:", "persyaratan_khusus_verbatim": "- Bukti kelahiran berupa:Akta kelahiran yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*.\n- Bukti perkawinan orang tua berupa:\nBukti pelaporan atau pencatatan pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil dan akta perkawinan yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*; atau\nBuku nikah atau akta perkawinan yang dikeluarkan oleh kementerian atau lembaga berwenang (jika perkawinan dilakukan di wilayah Indonesia).\n- Kartu Keluarga (KK) ayah/ibu Warga Negara Indonesia.\n*tidak diperlukan jika dokumen dalam bahasa Inggris", "pnbp_verbatim_for_reference_only": ["Masa tinggal 1 tahun : Rp. 6.000.000,-", "Komponen Biaya:", "- Biaya visa Rp 500.000", "- Izin tinggal terbatas Rp 3.000.000", "- Izin masuk kembali Rp 1.500.000", "- Biaya Verifikasi I Rp 1.000.000", "Masa tinggal 2 tahun : Rp. 8.500.000,-", "Komponen Biaya:", "- Biaya visa Rp 500.000", "- Izin tinggal terbatas Rp 5.000.000", "- Izin masuk kembali Rp 2.000.000", "- Biaya Verifikasi I Rp 1.000.000"], "prohibited_or_conditions_verbatim": ["melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."], "raw_path": "raw/E31D.html", "requirements_context_verbatim": [{"section": "Pengajuan visa", "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:"}, {"section": "Persyaratan khusus", "text": "Bukti pelaporan atau pencatatan pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil dan akta perkawinan yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*; atau\nBuku nikah atau akta perkawinan yang dikeluarkan oleh kementerian atau lembaga berwenang (jika perkawinan dilakukan di wilayah Indonesia)."}, {"section": "Persyaratan khusus", "text": "*tidak diperlukan jika dokumen dalam bahasa Inggris"}], "requirements_reference_verbatim": null, "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "Surat permohonan visa dari ayah/ibu Warga Negara Indonesia"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis, (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "Daftar riwayat hidup"}, {"n": 6, "section": "Pengajuan visa (berkas elektronik)", "text": "Riwayat perjalanan (itinerary)"}, {"n": 7, "section": "Persyaratan khusus", "text": "Bukti kelahiran berupa:Akta kelahiran yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*."}, {"n": 8, "section": "Persyaratan khusus", "text": "Bukti perkawinan orang tua berupa:"}, {"context_verbatim": "Bukti pelaporan atau pencatatan pada Perwakilan Republik Indonesia atau instansi yang berwenang di bidang pencatatan sipil dan akta perkawinan yang telah diterjemahkan dalam bahasa Indonesia oleh penerjemah tersumpah*; atau\nBuku nikah atau akta perkawinan yang dikeluarkan oleh kementerian atau lembaga berwenang (jika perkawinan dilakukan di wilayah Indonesia).", "n": 9, "section": "Persyaratan khusus", "text": "Kartu Keluarga (KK) ayah/ibu Warga Negara Indonesia."}], "retrieved_at": "2026-10-17T13:27:12Z", "sections_verbatim": [{"blocks": [{"kind": "context", "text": "melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"}], "heading": "Dengan visa ini, anda dapat", "id": "dengan-visa-ini-anda-dapat", "items": ["melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.", "Selama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"], "text": "melakukan kegiatan yang berhubungan dengan pekerjaan atau mengikuti pendidikan, sepanjang telah dilaporkan ke Imigrasi.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"}, {"blocks": [{"kind": "context", "text": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu ter