    TRUE,
    NULL,
    NULL,
    NULL,
    $j${"allowed_activities": "Tinggal dan menempuh pendidikan di Indonesia.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "code": "E31G", "definition_verbatim": "Tinggal dan menempuh pendidikan di Indonesia.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "entry": "multiple", "extendable": ["Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"], "http_status": 200, "itap_assessment": {"direct_itap_context_present": false, "family_evidence": "law/E31/ITAP.json", "itas_to_itap_eligible_as_stated": null, "status": "TO_VERIFY"}, "itap_verbatim": [{"kind": "generic_conversion", "section": "Jenis visa", "text": "Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E31G"}], "jenis_visa_verbatim": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "ketentuan_lain_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."], "not_found_evidence_verbatim": null, "notes": ["VERIFIED_FROM_SOURCE denotes faithful capture of the available page, not resolution of legal conflicts or missing fields.", "Only HTML entities, whitespace and structural list markers are normalized. Source spelling, punctuation, amounts and nested alternatives are retained.", "No offshore/onshore statement was found on the visa page; where_to_apply is null + TO_VERIFY. The evisa application channel is preserved separately.", "stay_days retains source year-based sentences; no conversion to a day count. total_max_verbatim is null when the visa page gives no cumulative limit.", "PNBP is reference only and is never a client price.", "Requirement numbers are extraction order, not official numbering. Nested alternatives remain grouped; section context and translation exceptions must be read with the items.", "A generic conversion sentence or a relative holding ITAP does not establish that this code can convert to ITAP. Code-specific conversion eligibility remains null + TO_VERIFY; see ITAP.json."], "official_name_id": "E31G Visa Keluarga Orang Tua dari Anak WNI", "page_sha256": "9529b5c1f963ae1d87df34aefd3f0a3613e4043ee00daaf365693c6f703e7d46", "pengajuan_intro_verbatim": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:", "persyaratan_khusus_verbatim": "Bukti hubungan hukum antara orang tua dan anak sebagaimana yang tercantum dalam kartu keluarga anak, di antaranya (pilih salah satu):\n- Akta kelahiran yang diterbitkan oleh instansi pemerintah yang berwenang di Indonesia;\n- Akta kelahiran yang telah diterjemahkan ke dalam bahasa Indonesia oleh penerjemah tersumpah kecuali dalam bahasa Inggris, jika anak tersebut lahir di luar negeri; atau\n- Akta penetapan anak jika anak tersebut bukan anak kandung atau anak luar nikah.", "pnbp_verbatim_for_reference_only": ["Masa tinggal hingga 1 tahun : Rp. 6.000.000,-", "Komponen biaya:", "- Visa Tinggal Terbatas: Rp500.000,00", "- Biaya Verifikasi Visa Kategori I: Rp1.000.000,00", "- Izin Tinggal Terbatas paling lama 1 tahun: Rp3.000.000,00", "- Izin Masuk Kembali paling lama 1 tahun: Rp1.500.000,00", "Masa tinggal hingga 2 tahun : Rp. 8.500.000,-", "Komponen biaya:", "- Visa Tinggal Terbatas: Rp500.000,00", "- Biaya Verifikasi Visa Kategori I: Rp1.000.000,00", "- Izin Tinggal Terbatas paling lama 2 tahun: Rp5.000.000,00", "- Izin Masuk Kembali paling lama 2 tahun: Rp2.000.000,00"], "prohibited_or_conditions_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."], "raw_path": "raw/E31G.html", "requirements_context_verbatim": [{"section": "Pengajuan visa", "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:"}, {"section": "Persyaratan khusus", "text": "Bukti hubungan hukum antara orang tua dan anak sebagaimana yang tercantum dalam kartu keluarga anak, di antaranya (pilih salah satu):"}], "requirements_reference_verbatim": null, "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "Surat permohonan visa dari anak yang merupakan WNI"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "Daftar riwayat hidup"}, {"n": 6, "section": "Pengajuan visa (berkas elektronik)", "text": "Riwayat perjalanan (itinerary)"}, {"n": 7, "section": "Persyaratan khusus", "text": "Bukti hubungan hukum antara orang tua dan anak sebagaimana yang tercantum dalam kartu keluarga anak, di antaranya (pilih salah satu):\n- Akta kelahiran yang diterbitkan oleh instansi pemerintah yang berwenang di Indonesia;\n- Akta kelahiran yang telah diterjemahkan ke dalam bahasa Indonesia oleh penerjemah tersumpah kecuali dalam bahasa Inggris, jika anak tersebut lahir di luar negeri; atau\n- Akta penetapan anak jika anak tersebut bukan anak kandung atau anak luar nikah."}], "retrieved_at": "2026-10-17T13:27:13Z", "sections_verbatim": [{"blocks": [{"kind": "context", "text": "Tinggal dan menempuh pendidikan di Indonesia.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"}], "heading": "Dengan visa ini, anda dapat", "id": "dengan-visa-ini-anda-dapat", "items": ["Tinggal dan menempuh pendidikan di Indonesia.", "Selama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"], "text": "Tinggal dan menempuh pendidikan di Indonesia.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"}, {"blocks": [{"kind": "context", "text": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya."}], "heading": "Jenis visa", "id": "jenis-visa", "items": ["Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.", "Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya."], "text": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya."}, {"blocks": [{"kind": "item", "text": "Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan."}, {"kind": "item", "text": "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"}], "heading": "Masa tinggal", "id": "masa-tinggal", "items": ["Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan.", "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"], "text": "- Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan.\n- Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"}, {"blocks": [{"kind": "context", "text": "Masa tinggal hingga 1 tahun : Rp. 6.000.000,-\nKomponen biaya:"}, {"kind": "item", "text": "Visa Tinggal Terbatas: Rp500.000,00"}, {"kind": "item", "text": "Biaya Verifikasi Visa Kategori I: Rp1.000.000,00"}, {"kind": "item", "text": "Izin Tinggal Terbatas paling lama 1 tahun: Rp3.000.000,00"}, {"kind": "item", "text": "Izin Masuk Kembali paling lama 1 tahun: Rp1.500.000,00"}, {"kind": "context", "text": "Masa tinggal hingga 2 tahun : Rp. 8.500.000,-\nKomponen biaya:"}, {"kind": "item", "text": "Visa Tinggal Terbatas: Rp500.000,00"}, {"kind": "item", "text": "Biaya Verifikasi Visa Kategori I: Rp1.000.000,00"}, {"kind": "item", "text": "Izin Tinggal Terbatas paling lama 2 tahun: Rp5.000.000,00"}, {"kind": "item", "text": "Izin Masuk Kembali paling lama 2 tahun: Rp2.000.000,00"}], "heading": "Biaya (PNBP)", "id": "biaya-pnbp", "items": ["Visa Tinggal Terbatas: Rp500.000,00", "Biaya Verifikasi Visa Kategori I: Rp1.000.000,00", "Izin Tinggal Terbatas paling lama 1 tahun: Rp3.000.000,00", "Izin Masuk Kembali paling lama 1 tahun: Rp1.500.000,00", "Visa Tinggal Terbatas: Rp500.000,00", "Biaya Verifikasi Visa Kategori I: Rp1.000.000,00", "Izin Tinggal Terbatas paling lama 2 tahun: Rp5.000.000,00", "Izin Masuk Kembali paling lama 2 tahun: Rp2.000.000,00"], "text": "Masa tinggal hingga 1 tahun : Rp. 6.000.000,-\nKomponen biaya:\n- Visa Tinggal Terbatas: Rp500.000,00\n- Biaya Verifikasi Visa Kategori I: Rp1.000.000,00\n- Izin Tinggal Terbatas paling lama 1 tahun: Rp3.000.000,00\n- Izin Masuk Kembali paling lama 1 tahun: Rp1.500.000,00\nMasa tinggal hingga 2 tahun : Rp. 8.500.000,-\nKomponen biaya:\n- Visa Tinggal Terbatas: Rp500.000,00\n- Biaya Verifikasi Visa Kategori I: Rp1.000.000,00\n- Izin Tinggal Terbatas paling lama 2 tahun: Rp5.000.000,00\n- Izin Masuk Kembali paling lama 2 tahun: Rp2.000.000,00"}, {"blocks": [{"kind": "context", "text": "Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."}], "heading": "Penjamin (Sponsor)", "id": "penjamin-sponsor", "items": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."], "text": "Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."}, {"blocks": [{"kind": "context", "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:"}, {"kind": "item", "text": "Surat permohonan visa dari anak yang merupakan WNI"}, {"kind": "item", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,"}, {"kind": "item", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara"}, {"kind": "item", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"kind": "item", "text": "Daftar riwayat hidup"}, {"kind": "item", "text": "Riwayat perjalanan (itinerary)"}], "heading": "Pengajuan visa", "id": "pengajuan-visa", "items": ["Surat permohonan visa dari anak yang merupakan WNI", "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,", "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara", "pasfoto berwarna terbaru (setahun terakhir). Detail", "Daftar riwayat hidup", "Riwayat perjalanan (itinerary)"], "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:\n- Surat permohonan visa dari anak yang merupakan WNI\n- Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,\n- bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara\n- pasfoto berwarna terbaru (setahun terakhir). Detail\n- Daftar riwayat hidup\n- Riwayat perjalanan (itinerary)"}, {"blocks": [{"kind": "context", "text": "Bukti hubungan hukum antara orang tua dan anak sebagaimana yang tercantum dalam kartu keluarga anak, di antaranya (pilih salah satu):"}, {"kind": "item", "text": "Akta kelahiran yang diterbitkan oleh instansi pemerintah yang berwenang di Indonesia;"}, {"kind": "item", "text": "Akta kelahiran yang telah diterjemahkan ke dalam bahasa Indonesia oleh penerjemah tersumpah kecuali dalam bahasa Inggris, jika anak tersebut lahir di luar negeri; atau"}, {"kind": "item", "text": "Akta penetapan anak jika anak tersebut bukan anak kandung atau anak luar nikah."}], "heading": "Persyaratan khusus", "id": "persyaratan-khusus", "items": ["Akta kelahiran yang diterbitkan oleh instansi pemerintah yang berwenang di Indonesia;", "Akta kelahiran yang telah diterjemahkan ke dalam bahasa Indonesia oleh penerjemah tersumpah kecuali dalam bahasa Inggris, jika anak tersebut lahir di luar negeri; atau", "Akta penetapan anak jika anak tersebut bukan anak kandung atau anak luar nikah."], "text": "Bukti hubungan hukum antara orang tua dan anak sebagaimana yang tercantum dalam kartu keluarga anak, di antaranya (pilih salah satu):\n- Akta kelahiran yang diterbitkan oleh instansi pemerintah yang berwenang di Indonesia;\n- Akta kelahiran yang telah diterjemahkan ke dalam bahasa Indonesia oleh penerjemah tersumpah kecuali dalam bahasa Inggris, jika anak tersebut lahir di luar negeri; atau\n- Akta penetapan anak jika anak tersebut bukan anak kandung atau anak luar nikah."}, {"blocks": [{"kind": "item", "text": "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia."}, {"kind": "item", "text": "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal."}, {"kind": "item", "text": "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi."}, {"kind": "item", "text": "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."}], "heading": "Ketentuan lain", "id": "ketentuan-lain", "items": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."], "text": "- Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.\n- Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.\n- Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.\n- Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya."}, {"blocks": [{"kind": "context", "text": "Pengajuan Visa di Direktorat Jenderal Imigrasi:"}, {"kind": "item", "text": "pemeriksaan kelengkapan persyaratan;"}, {"kind": "item", "text": "verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;"}, {"kind": "item", "text": "pembuatan profil dan verifikasi;"}, {"kind": "item", "text": "persetujuan;"}, {"kind": "item", "text": "penerbitan visa."}, {"kind": "context", "text": "Waktu proses lima hari kerja setelah pembayaran visa diterima."}], "heading": "Proses pengajuan dan pemberian visa", "id": "proses-pengajuan-dan-pemberian-visa", "items": ["pemeriksaan kelengkapan persyaratan;", "verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;", "pembuatan profil dan verifikasi;", "persetujuan;", "penerbitan visa."], "text": "Pengajuan Visa di Direktorat Jenderal Imigrasi:\n- pemeriksaan kelengkapan persyaratan;\n- verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;\n- pembuatan profil dan verifikasi;\n- persetujuan;\n- penerbitan visa.\nWaktu proses lima hari kerja setelah pembayaran visa diterima."}, {"blocks": [{"kind": "item", "text": "Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM"}, {"kind": "item", "text": "Peraturan Menteri Hukum dan HAM RI Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal"}, {"kind": "item", "text": "Peraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal"}, {"kind": "item", "text": "Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa"}, {"kind": "item", "text": "Peraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI"}, {"kind": "item", "text": "Peraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"}], "heading": "Dasar hukum", "id": "dasar-hukum", "items": ["Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM", "Peraturan Menteri Hukum dan HAM RI Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal", "Peraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal", "Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa", "Peraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI", "Peraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"], "text": "- Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM\n- Peraturan Menteri Hukum dan HAM RI Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal\n- Peraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal\n- Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa\n- Peraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI\n- Peraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"}], "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E31G", "sponsor_required": {"as_stated_boolean": true, "invitation_requirement_see": "requirements_verbatim", "verbatim": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan."], "subjek_verbatim": null, "to_verify": ["where_to_apply", "itas_to_itap_eligible_as_stated", "total_max_verbatim"], "total_max_verbatim": null, "verification_issues": [], "where_to_apply": null}$j$::jsonb,
